"""Existing desktop workflow accepts purchased finished goods without production."""
import sys,tempfile,threading
from pathlib import Path
sys.path.insert(0,str(Path(__file__).resolve().parents[1]))
from demo import create_demo
from app import Server
from playwright.sync_api import sync_playwright,expect
with tempfile.TemporaryDirectory() as td:
 store=create_demo(Path(td)/'ceh.sqlite3');server=Server(('127.0.0.1',0),td);thread=threading.Thread(target=server.serve_forever,daemon=True);thread.start()
 try:
  with sync_playwright() as p:
   browser=p.chromium.launch(executable_path='/usr/bin/chromium',headless=True,args=['--no-sandbox']);page=browser.new_page(viewport={'width':1600,'height':1100},locale='ru-RU');errors=[];page.on('pageerror',lambda e:errors.append(str(e)));page.goto(f'http://127.0.0.1:{server.server_port}/#catalog');expect(page.locator('h1')).to_have_text('Номенклатура');page.locator('#employee').fill('Кладовщик');page.locator('#employee').dispatch_event('change')
   page.get_by_role('button',name='＋ Добавить позицию').click();page.locator('[name=name]').fill('Покупной десерт');page.locator('[name=kind]').select_option('finished');page.locator('[name=unit]').select_option('уп.');page.locator('[name=supply_type]').select_option('resale');expect(page.locator('[name=labor_rate]')).to_be_disabled();page.locator('[name=price]').fill('70');page.locator('[name=sale_price]').fill('200');page.get_by_role('button',name='Сохранить',exact=True).click();expect(page.locator('#modal')).not_to_be_visible();page.locator('[data-filter="catalog.supply"]').select_option('resale');page.get_by_role('button',name='Раскрыть всё').click();expect(page.locator('#catalog-tree')).to_contain_text('Покупной десерт');expect(page.locator('#catalog-tree')).not_to_contain_text('Куриное филе сувид')
   iid=next(i['id'] for i in store.snapshot()['items'] if i['name']=='Покупной десерт');page.locator('#nav a[href="#stock"]').click();page.get_by_role('button',name='＋ Приёмка').click();page.locator('[name=partner_id]').select_option(label='Фермерский двор');page.locator('.r-item').select_option(str(iid));page.locator('.r-qty').fill('3');expect(page.locator('.r-price')).to_have_value('70');expect(page.locator('.r-exp')).to_be_disabled();page.get_by_role('button',name='Провести приёмку').click();expect(page.locator('#modal')).not_to_be_visible();assert next(i for i in store.snapshot()['items'] if i['id']==iid)['available']==3
   page.locator('#nav a[href="#orders"]').click();page.get_by_role('button',name='＋ Новый заказ').click();page.locator('[name=client_id]').select_option(label='Кофейня «Тёплый хлеб»');page.locator('.r-item').select_option(str(iid));page.locator('.r-qty').fill('4');due=page.locator('[name=due]').input_value();page.get_by_role('button',name='Сохранить',exact=True).click();expect(page.locator('#modal')).not_to_be_visible();page.locator('#nav a[href="#production"]').click();page.locator('#plan-date').fill(due[:10]);expect(page.locator('#content')).to_contain_text('Потребность в закупке');pstate=store.plan(due[:10]);assert next(r for r in pstate['purchases'] if r['item_id']==iid)['purchase']==1;assert not any(r['item_id']==iid for r in pstate['products'])
   page.get_by_role('button',name='＋ Выпуск на склад').click();assert page.locator('[name=item_id] option').filter(has_text='Покупной десерт').count()==0;page.locator('[data-action="close-modal"]').first.click();assert not errors,errors;browser.close();print('Resale desktop browser passed: type, no wages/recipe, catalogue filter, receipt, prices, purchase-only shortage and excluded production picker.')
 finally:server.shutdown();server.server_close();thread.join()
